/**
 * The compiled semantic-convention registry (rfc/semantic-convention-provenance.md §1) and its
 * shared-resource register source (rfc/semantic-convention-register.md).
 *
 * `CONVENTION_DECLARATIONS` is the one literal runtime authority for every declared convention a
 * projection may depend on. Its prefix is generated byte-for-byte from the reviewed source-recovery
 * artifact `planning/semantic-convention-provenance/initial-declarations.json` by
 * `tools/generate-initial-convention-declarations.mjs` (`make semantic-convention-source-check`);
 * later declarations are authored directly beneath it. Each landed `id@version` has exactly one
 * append-only row in `evidence-convention-history.jsonl` (`make semantic-convention-history-check`).
 *
 * `SEMANTIC_CONVENTION_MEMBERS` is the literal string tuple the shared-resource catalogue reads
 * (`rfc/shared-resource-registers.json`, `string_tuple` reader). One member per declaration, in the
 * register's member grammar: `space@1` is `space_v1`, `defence-duty@1` is `defence_duty_v1`.
 * `evidence-conventions.test.ts` proves the tuple and the declarations are one set.
 *
 * A convention is a *definition*, not grounding: it never promotes a projection's grounding,
 * exactness or confidence, and it is never a learner-facing setting.
 */
import { evidenceDigest } from "./evidence-contract.js";

export interface ConventionRef {
  readonly id: string;
  readonly version: number;
}

export type ConventionAuthority =
  | Readonly<{ kind: "position_rules"; implementation: string }>
  | Readonly<{ kind: "landed_contract"; witnesses: readonly string[]; snapshotRef: string }>
  | Readonly<{ kind: "published_source"; citation: string; licence: string }>
  | Readonly<{ kind: "product_rule"; rulingRef: string }>
  | Readonly<{ kind: "measured_record"; recordRef: string }>;

export type ConventionDisclosure =
  | Readonly<{ kind: "definition_and_limitations" }>
  | Readonly<{ kind: "reviewed_text"; summary: string; detail: string }>;

export interface ConventionDeclaration {
  readonly ref: ConventionRef;
  readonly definition: string;
  readonly limitations: readonly string[];
  readonly authority: readonly ConventionAuthority[];
  readonly disclosure: ConventionDisclosure;
}

export interface CompiledConventionRegistry {
  /** Ordered by `(id, version)`; frozen. */
  readonly declarations: readonly ConventionDeclaration[];
  /** `sha256:<hex>` over every semantic field, independent of declaration order or file path. */
  readonly digest: string;
}

