// ---------------------------------------------------------------------------------------------
// Identity grammar
// ---------------------------------------------------------------------------------------------

const BASE_ID = /^[a-z][a-z0-9_-]*$/u;
const REF_TEXT = /^([a-z][a-z0-9_-]*)@([1-9][0-9]*)$/u;
const SHA256 = /^sha256:[0-9a-f]{64}$/u;

export class ConventionRegistryError extends TypeError {
  constructor(readonly code: string, message: string) {
    super(`${code}: ${message}`);
    this.name = "ConventionRegistryError";
  }
}

export function conventionRefKey(ref: ConventionRef): string {
  return `${ref.id}@${ref.version}`;
}

/** Parses an exact `id@version` ref; version is a canonical positive safe integer. */
export function parseConventionRef(text: string): ConventionRef {
  const match = typeof text === "string" ? text.match(REF_TEXT) : null;
  if (match === null || !Number.isSafeInteger(Number(match[2]))) throw new ConventionRegistryError("CONVENTION_REF_INVALID", `${String(text)} is not an exact id@version ref`);
  return Object.freeze({ id: match[1]!, version: Number(match[2]) });
}

/** The register's member spelling: `defence-duty@1` is `defence_duty_v1`. */
export function conventionMember(ref: ConventionRef): string {
  return `${ref.id.replaceAll("-", "_")}_v${ref.version}`;
}

export function compareConventionRefs(left: ConventionRef, right: ConventionRef): number {
  return left.id < right.id ? -1 : left.id > right.id ? 1 : left.version - right.version;
}

const text = (value: unknown): value is string => typeof value === "string" && value.trim() !== "";
const exactKeys = (value: unknown, keys: readonly string[]): boolean =>
  typeof value === "object" && value !== null && !Array.isArray(value) && Object.keys(value).length === keys.length && keys.every((key) => Object.hasOwn(value, key));

function assertAuthority(ref: string, authority: unknown): void {
  const shape = (keys: readonly string[]): boolean => exactKeys(authority, keys);
  const item = authority as Record<string, unknown>;
  const valid = typeof authority === "object" && authority !== null && (
    (item.kind === "position_rules" && shape(["kind", "implementation"]) && text(item.implementation))
    || (item.kind === "landed_contract" && shape(["kind", "witnesses", "snapshotRef"]) && Array.isArray(item.witnesses) && item.witnesses.length > 0
      && item.witnesses.every(text) && typeof item.snapshotRef === "string" && /^[0-9a-f]{7,40}$/u.test(item.snapshotRef))
    // A citation must resolve to a retrievable URL; a ruling to a ledger id.
    || (item.kind === "published_source" && shape(["kind", "citation", "licence"]) && text(item.citation) && /https:\/\/\S+/u.test(item.citation as string) && text(item.licence))
    || (item.kind === "product_rule" && shape(["kind", "rulingRef"]) && typeof item.rulingRef === "string" && /^\[\[D\d+[a-z]?\]\]$/u.test(item.rulingRef))
    || (item.kind === "measured_record" && shape(["kind", "recordRef"]) && text(item.recordRef))
  );
  if (!valid) throw new ConventionRegistryError("CONVENTION_AUTHORITY_INVALID", `${ref} carries an unsupported or unresolvable authority ${JSON.stringify(authority)}`);
}

/** The semantic image of one declaration: every field, canonical key order, no path or position. */
function semanticImage(declaration: ConventionDeclaration): unknown {
  return {
    ref: { id: declaration.ref.id, version: declaration.ref.version },
    definition: declaration.definition,
    limitations: [...declaration.limitations],
    authority: declaration.authority.map((authority) => ({ ...authority })),
    disclosure: { ...declaration.disclosure },
  };
}

/** `sha256:<hex>` digest of one declaration's complete semantic image. */
export function conventionSemanticDigest(declaration: ConventionDeclaration): string {
  return `sha256:${evidenceDigest(semanticImage(declaration))}`;
}

/**
 * Freezes and orders declarations by `(id, version)`. Refuses duplicate refs, malformed refs, a
 * skipped or backward lineage (`id@2` needs `id@1`), blank definition/limitations/disclosure and
 * any unsupported authority shape. The digest covers every semantic field, never order or path.
 */
export function compileConventionRegistry(declarations: readonly ConventionDeclaration[]): CompiledConventionRegistry {
  if (!Array.isArray(declarations)) throw new ConventionRegistryError("CONVENTION_REGISTRY_INVALID", "declarations must be an array");
  const seen = new Set<string>();
  const members = new Set<string>();
  for (const declaration of declarations) {
    if (!exactKeys(declaration, ["ref", "definition", "limitations", "authority", "disclosure"])) throw new ConventionRegistryError("CONVENTION_DECLARATION_INVALID", "a declaration must have exactly ref, definition, limitations, authority and disclosure");
    const ref = declaration.ref;
    if (!exactKeys(ref, ["id", "version"]) || !BASE_ID.test(ref.id) || !Number.isSafeInteger(ref.version) || ref.version < 1) throw new ConventionRegistryError("CONVENTION_REF_INVALID", `malformed ref ${JSON.stringify(ref)}`);
    const key = conventionRefKey(ref);
    if (seen.has(key)) throw new ConventionRegistryError("CONVENTION_REF_DUPLICATE", `${key} is declared twice`);
    seen.add(key);
    const member = conventionMember(ref);
    if (members.has(member)) throw new ConventionRegistryError("CONVENTION_MEMBER_ALIAS", `${key} aliases register member ${member}`);
    members.add(member);
    if (!text(declaration.definition)) throw new ConventionRegistryError("CONVENTION_DECLARATION_BLANK", `${key} has a blank definition`);
    if (!Array.isArray(declaration.limitations) || declaration.limitations.length === 0 || !declaration.limitations.every(text)) throw new ConventionRegistryError("CONVENTION_DECLARATION_BLANK", `${key} needs at least one non-blank mandatory limitation`);
    if (!Array.isArray(declaration.authority) || declaration.authority.length === 0) throw new ConventionRegistryError("CONVENTION_AUTHORITY_INVALID", `${key} needs at least one authority`);
    for (const authority of declaration.authority) assertAuthority(key, authority);
    const disclosure = declaration.disclosure as Record<string, unknown>;
    const disclosureValid = (disclosure?.kind === "definition_and_limitations" && exactKeys(disclosure, ["kind"]))
      || (disclosure?.kind === "reviewed_text" && exactKeys(disclosure, ["kind", "summary", "detail"]) && text(disclosure.summary) && text(disclosure.detail));
    if (!disclosureValid) throw new ConventionRegistryError("CONVENTION_DECLARATION_BLANK", `${key} has a blank or unsupported disclosure`);
  }
  for (const key of seen) {
    const { id, version } = parseConventionRef(key);
    if (version > 1 && !seen.has(`${id}@${version - 1}`)) throw new ConventionRegistryError("CONVENTION_LINEAGE_SKIPPED", `${key} has no ${id}@${version - 1} predecessor`);
  }
  const ordered = [...declarations].sort((left, right) => compareConventionRefs(left.ref, right.ref));
  const digest = `sha256:${evidenceDigest(ordered.map(semanticImage))}`;
  return deepFreeze({ declarations: ordered.map((declaration) => deepFreeze(structuredCloneDeclaration(declaration))), digest });
}

function structuredCloneDeclaration(declaration: ConventionDeclaration): ConventionDeclaration {
  return semanticImage(declaration) as ConventionDeclaration;
}

export const CONVENTION_REGISTRY: CompiledConventionRegistry = compileConventionRegistry(CONVENTION_DECLARATIONS);

const DECLARATION_BY_KEY: ReadonlyMap<string, ConventionDeclaration> = new Map(CONVENTION_REGISTRY.declarations.map((declaration) => [conventionRefKey(declaration.ref), declaration]));

export function registeredConvention(ref: ConventionRef): ConventionDeclaration | undefined {
  return DECLARATION_BY_KEY.get(conventionRefKey(ref));
}

export function isRegisteredConvention(ref: ConventionRef): boolean {
  return DECLARATION_BY_KEY.has(conventionRefKey(ref));
}

// ---------------------------------------------------------------------------------------------
// Value-level convention receipt (rfc/semantic-convention-provenance.md §4; [[D1921]])
// ---------------------------------------------------------------------------------------------

export type ConventionDerivationReceipt =
  | Readonly<{ kind: "source" }>
  | Readonly<{
      kind: "derived";
      /** Canonical sorted exact-projection identity of the declared member actually used. */
      member: string;
      /** Canonical multiset of every concrete sealed input value (order-free, multiplicity kept). */
      inputs: readonly Readonly<{ projection: string; valueDigest: string }>[];
    }>;

export interface ConventionReceipt {
  readonly refs: readonly ConventionRef[];
  readonly registryDigest: string;
  readonly derivation: ConventionDerivationReceipt;
  readonly digest: string;
}

/**
 * Builds one frozen receipt. `refs` are validated against the registry and canonicalized; input
 * entries are sorted so input order never changes the receipt while multiplicity does.
 */
export function conventionReceipt(refs: readonly ConventionRef[], derivation: ConventionDerivationReceipt, registry: CompiledConventionRegistry = CONVENTION_REGISTRY): ConventionReceipt {
  const byKey = new Map<string, ConventionRef>();
  for (const ref of refs) {
    const key = conventionRefKey(ref);
    if (registry === CONVENTION_REGISTRY ? !DECLARATION_BY_KEY.has(key) : !registry.declarations.some((declaration) => conventionRefKey(declaration.ref) === key)) {
      throw new ConventionRegistryError("CONVENTION_REF_UNREGISTERED", `${key} is not a registered convention`);
    }
    byKey.set(key, Object.freeze({ id: ref.id, version: ref.version }));
  }
  const canonicalRefs = [...byKey.values()].sort(compareConventionRefs);
  const canonicalDerivation: ConventionDerivationReceipt = derivation.kind === "source"
    ? { kind: "source" }
    : {
        kind: "derived",
        member: derivation.member,
        inputs: [...derivation.inputs].map((input) => ({ projection: input.projection, valueDigest: input.valueDigest }))
          .sort((left, right) => left.projection < right.projection ? -1 : left.projection > right.projection ? 1 : left.valueDigest < right.valueDigest ? -1 : left.valueDigest > right.valueDigest ? 1 : 0),
      };
  const body = { refs: canonicalRefs.map((ref) => ({ id: ref.id, version: ref.version })), registryDigest: registry.digest, derivation: canonicalDerivation };
  return deepFreeze({ ...body, refs: canonicalRefs, digest: `sha256:${evidenceDigest(body)}` });
}

export function isConventionDigest(value: unknown): value is string {
  return typeof value === "string" && SHA256.test(value);
}

function deepFreeze<T>(value: T): T {
  if (value !== null && typeof value === "object" && !Object.isFrozen(value)) {
    for (const entry of Object.values(value as Record<string, unknown>)) deepFreeze(entry);
    Object.freeze(value);
  }
  return value;
}
